head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gDepCd;
scwin.gRowCnt;
scwin.gStat;
scwin.gSrhCnt;

//교체요구 대상자 관리
scwin.vScrenID = 'ULDSTF35116.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '6') {
        //grd_Grid.ColumnProp("MKT_NM", "Show") = false;
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(panel_mkt, false);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, "2");
    }

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜


    /* 03906 : DISCLS_PRN_REPC_RSN_CD : 공시대상자교체사유코드	*/
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_M_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.dsclmgt.repcreqprn.select.rsncd";
    dts_RepcRsnCd.DataID = encodeURI(url);
    dts_RepcRsnCd.reset();
    var url_list = "/PenaltyImposition.do?method=listRepcReqPrnIsurCd&inputMessageId=REPCREQPRN_CHECK_INOUT" + "&outputMessageId=REPCREQPRN_CHECK_INOUT";

    // 디폴트 전체로해서 조회함.						
    var url_cond = "&EMP_NO=" + scwin.gEmpNo;
    dts_bycorpChrg.DataID = encodeURI(url_list + url_cond);
    dts_bycorpChrg.reset();
};
scwin.fn_Search = function() {
    var url_list = "/PenaltyImposition.do?method=listRepcReqPrn&inputMessageId=REPCREQPRN_INOUT" + "&outputMessageId=REPCREQPRN_INOUT";

    // 디폴트 전체로해서 조회함.						
    var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + "&TO_DATE=" + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&OBJ_NM=" + $c.stf.getObjectValue(cmb_objnm) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_Grid);
    dts_RepcReqPrn.DataID = encodeURI(url_list + url_cond);
    dts_RepcReqPrn.reset();
};




// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_RepcReqPrn.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_RepcReqPrn.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_save = function() {
    var gCnt = 0;
    for (var k = 1; k <= dts_RepcReqPrn.getTotalRow(); k++) {
        scwin.gStat = dts_RepcReqPrn.getRowStatus(k);
        if (scwin.gStat == TB_JOB_INSERT) {
            gCnt++;
            dts_RepcReqPrn.setCellData(k, "SEQ", gCnt);
        }
    }
    grd_Grid.Redraw = true;
    if (window.confirm("저장하시겠습니까?")) {
        var url = "/PenaltyImposition.do?method=saveRepcReqPrn&EMP_NO=" + scwin.gEmpNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_RepcReqPrn)";
        trs_save.Post();
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "ACPT_NO") {
        if (scwin.gAcptNo != "" && scwin.gAcptNo.length > 0) {
            $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
        } else {
            $c.win.alert("공시뷰어를 볼 수 없습니다");
        }
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    await $c.frame.CreateDialogFrame("ONLYFORGRID", "/common/ULDCOM00007_POP.gfm", "회사검색", 10, 10, 10, 20, "window");
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.dts_RepcReqPrn_OnLoadError = function() {
    $c.stf.alert_error(dts_RepcReqPrn);
};
scwin.dts_RepcReqPrn_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    scwin.gSrhCnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "교체요구대상자관리", "", "8");
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_Save1_onclick = function() {
    //저장은 해당행의 현재종목담당자만 할 수 있음 20160219
    //회사코드를 가져와서 종목에 있는지 확인해야함

    scwin.gRowCnt = 0;
    var gStatCnt = 0;
    var gIsurCdStr = "";
    for (var k = 1; k <= dts_RepcReqPrn.getTotalRow(); k++) {
        scwin.gStat = dts_RepcReqPrn.getRowStatus(k);
        if (scwin.gStat == '1' || scwin.gStat == '3') {
            gStatCnt++;
            gIsurCdStr = dts_RepcReqPrn.getCellData(k, "ISUR_CD");
            for (var j = 1; j <= dts_bycorpChrg.getTotalRow(); j++) {
                if (gIsurCdStr == dts_bycorpChrg.getCellData(j, "ISUR_CD")) {
                    scwin.gRowCnt++;
                    break;
                }
            }
        }
    }
    if (scwin.gSrhCnt == dts_RepcReqPrn.getTotalRow() && gStatCnt <= 0) {
        $c.win.alert("변경된 사항이 없습니다.");
    } else {
        if (gStatCnt == scwin.gRowCnt) {
            scwin.fn_save();
        } else {
            $c.win.alert("해당 회사의 종목담당자만 입력 또는 수정이 가능합니다.");
        }
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert("성공적으로 저장 되었습니다.");
    scwin.fn_Search();
};
scwin.trs_save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();

    //조건검색에 교체요구일
    $c.stf.showObj(panel_2, false);
};
scwin.btn_AddRow_onclick = function() {
    //행삽입은 (코)공시1팀~3팀 만 할 수 있다.  20160219
    //코_공시4팀 추가 2018.04.09
    //코_T1,T2팀 추가 2020.03.20
    //3495 추가 2021.03.12
    if (scwin.gDepCd == '3420' || scwin.gDepCd == '3430' || scwin.gDepCd == '3440' || scwin.gDepCd == '3460' || scwin.gDepCd == '3490' || scwin.gDepCd == '3495' || scwin.gDepCd == '3470' || scwin.gDepCd == '3480') {
        if (dts_RepcReqPrn.getTotalRow() <= 0) {
            dts_RepcReqPrn.insertRow();
        } else {
            dts_RepcReqPrn.insertRow(dts_RepcReqPrn.getRowPosition() - 1);
        }
    } else {
        $c.win.alert("행삽입 권한이 없습니다.");
    }
};
scwin.btn_DelRow_onclick = function() {
    scwin.gAcptNo = dts_RepcReqPrn.getCellData(dts_RepcReqPrn.getRowPosition(), "ACPT_NO");
    scwin.gIsurCd = dts_RepcReqPrn.getCellData(dts_RepcReqPrn.getRowPosition(), "ISUR_CD");
    //alert("gAcptNo : " + gAcptNo);
    var gLstChgEmpNo = dts_RepcReqPrn.getCellData(dts_RepcReqPrn.getRowPosition(), "LST_CHG_EMP_NO");
    if (scwin.gAcptNo != '' && scwin.gAcptNo.length > 0) {
        //행삭제는 공시로 추출된 내용은 삭제불가, 20160219
        $c.win.alert("불성시법인 지정 공시로 추출된 행은 삭제 할 수 없습니다.");
    } else {
        //행삽입으로 생성된 행에 대해서는 입력한 사람만 삭제가능 20160219
        if (gLstChgEmpNo != '' && gLstChgEmpNo.length > 0) {
            if (gLstChgEmpNo == scwin.gEmpNo) {
                $c.cp.removeRow(dts_RepcReqPrn, dts_RepcReqPrn.getRowPosition());
            } else {
                $c.win.alert("해당 행을 입력한 사용자가 아니므로 행삭제를 할 수 없습니다.");
            }
            /*else{
            	//종목담당자도 삭제 가능
            	gRowCnt = 0;
            	for (var j = 1; j <= dts_bycorpChrg.CountRow; j++) {
            		if(gIsurCd == dts_bycorpChrg.NameString(j,"ISUR_CD")){
            			gRowCnt ++;
            			break;
            		}
            	}
            	if(gRowCnt > 0 ){
            		dts_RepcReqPrn.DeleteRow(dts_RepcReqPrn.RowPosition);
            	}
            	else{
            		alert("해당 행을 입력한 사용자가 아니거나 해당 회사의 종목담당자가 아니므로 행삭제를 할 수 없습니다.");
            	}
            }*/
        }
        //저장전 행삽입한 것을 삭제할때
        else {
            $c.cp.removeRow(dts_RepcReqPrn, dts_RepcReqPrn.getRowPosition());
        }
    }
};
